{"sql": "SELECT UPPER(species_scientific_name) as upper_sci, species_scientific_name, fall_color
FROM `bigquery-public-data.new_york.tree_species`
WHERE UPPER(species_scientific_name) NOT IN (
  SELECT UPPER(spc_latin) FROM `bigquery-public-data.new_york.tree_census_1995` WHERE spc_latin IS NOT NULL AND spc_latin NOT IN ('PLANTING SITE', 'UNKNOWN LIVE TREES', 'UNKNOWN DEAD TREES', 'UNKNOWN STUMP', 'STUMP', 'PINUS SPECIES')
)
ORDER BY upper_sci", "preview_rows": 30}
